1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "$id": "https://gitroll.dev/curriculum/challenges/regulatory-compliance/snapshot.schema.json",
4	  "title": "Regulatory Compliance Stage Snapshot",
5	  "type": "object",
6	  "additionalProperties": true,
7	  "required": ["schema_version", "snapshot_id", "run_id", "stage", "sequence", "created_at", "status", "predecessor", "consumed_record_ids", "produced_record_ids", "state", "unresolved", "decisions"],
8	  "properties": {
9	    "schema_version": {"const": "regulatory-compliance-stage-snapshot/2"},
10	    "snapshot_id": {"type": "string", "minLength": 1},
11	    "run_id": {"type": "string", "minLength": 1},
12	    "stage": {"enum": ["scope", "source-capture", "authority-and-timing", "evidence-reconciliation", "impact-analysis", "actions-and-approvals", "publication-validation"]},
13	    "sequence": {"type": "integer", "minimum": 1, "maximum": 7},
14	    "created_at": {"type": "string", "format": "date-time"},
15	    "status": {"enum": ["complete", "partial", "blocked", "failed"]},
16	    "predecessor": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/predecessor"}]},
17	    "consumed_record_ids": {"$ref": "#/$defs/recordIds"},
18	    "produced_record_ids": {"$ref": "#/$defs/recordIds"},
19	    "state": {"type": "object", "additionalProperties": true},
20	    "unresolved": {"$ref": "#/$defs/records"},
21	    "decisions": {"type": "array", "items": {"$ref": "#/$defs/decisionRecord"}}
22	  },
23	  "allOf": [
24	    {
25	      "if": {"properties": {"sequence": {"const": 1}}, "required": ["sequence"]},
26	      "then": {"properties": {"predecessor": {"type": "null"}, "consumed_record_ids": {"maxItems": 0}}},
27	      "else": {"properties": {"predecessor": {"$ref": "#/$defs/predecessor"}, "consumed_record_ids": {"minItems": 1}}}
28	    },
29	    {
30	      "if": {"properties": {"stage": {"const": "scope"}}, "required": ["stage"]},
31	      "then": {"properties": {"sequence": {"const": 1}, "state": {"required": ["as_of", "review_type", "systems_in_scope", "audiences", "approval_gates"], "properties": {"as_of": {"type": "string", "format": "date-time"}, "review_type": {"type": "string", "minLength": 1}, "systems_in_scope": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}}, "audiences": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}}, "approval_gates": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}}}}}}
32	    },
33	    {
34	      "if": {"properties": {"stage": {"const": "source-capture"}}, "required": ["stage"]},
35	      "then": {"properties": {"sequence": {"const": 2}, "state": {"required": ["sources"], "properties": {"sources": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/sourceRecord"}}}}}}
36	    },
37	    {
38	      "if": {"properties": {"stage": {"const": "authority-and-timing"}}, "required": ["stage"]},
39	      "then": {"properties": {"sequence": {"const": 3}, "state": {"required": ["binding_rules", "timing_rules", "guidance_context", "authority_blockers"], "properties": {"binding_rules": {"$ref": "#/$defs/records"}, "timing_rules": {"$ref": "#/$defs/records"}, "guidance_context": {"$ref": "#/$defs/records"}, "authority_blockers": {"$ref": "#/$defs/records"}}}}}
40	    },
41	    {
42	      "if": {"properties": {"stage": {"const": "evidence-reconciliation"}}, "required": ["stage"]},
43	      "then": {"properties": {"sequence": {"const": 4}, "state": {"required": ["system_facts", "policy_controls", "incident_evidence", "conflicts", "evidence_gaps"], "properties": {"system_facts": {"$ref": "#/$defs/records"}, "policy_controls": {"$ref": "#/$defs/records"}, "incident_evidence": {"$ref": "#/$defs/records"}, "conflicts": {"$ref": "#/$defs/records"}, "evidence_gaps": {"$ref": "#/$defs/records"}}}}}
44	    },
45	    {
46	      "if": {"properties": {"stage": {"const": "impact-analysis"}}, "required": ["stage"]},
47	      "then": {"properties": {"sequence": {"const": 5}, "state": {"required": ["impacts", "unaffected_items", "conflicts", "unresolved_items"], "properties": {"impacts": {"type": "array", "items": {"$ref": "#/$defs/impactRecord"}}, "unaffected_items": {"$ref": "#/$defs/records"}, "conflicts": {"$ref": "#/$defs/records"}, "unresolved_items": {"$ref": "#/$defs/records"}}}}}
48	    },
49	    {
50	      "if": {"properties": {"stage": {"const": "actions-and-approvals"}}, "required": ["stage"]},
51	      "then": {"properties": {"sequence": {"const": 6}, "state": {"required": ["proposed_actions", "approval_requirements", "escalations"], "properties": {"proposed_actions": {"$ref": "#/$defs/records"}, "approval_requirements": {"type": "array", "items": {"$ref": "#/$defs/approvalRecord"}}, "escalations": {"$ref": "#/$defs/records"}}}}}
52	    },
53	    {
54	      "if": {"properties": {"stage": {"const": "publication-validation"}}, "required": ["stage"]},
55	      "then": {"properties": {"sequence": {"const": 7}, "state": {"required": ["artifacts", "validation_checks", "publication_status"], "properties": {"artifacts": {"type": "array", "items": {"$ref": "#/$defs/artifactRecord"}}, "validation_checks": {"$ref": "#/$defs/records"}, "publication_status": {"enum": ["validated", "blocked", "failed"]}}}}}
56	    }
57	  ],
58	  "$defs": {
59	    "recordIds": {"type": "array", "items": {"type": "string", "minLength": 1}, "uniqueItems": true},
60	    "predecessor": {"type": "object", "additionalProperties": false, "required": ["snapshot_id", "path", "sha256"], "properties": {"snapshot_id": {"type": "string", "minLength": 1}, "path": {"type": "string", "minLength": 1}, "sha256": {"type": "string", "pattern": "^sha256:[0-9a-f]{64}$"}}},
61	    "record": {"type": "object", "additionalProperties": true, "required": ["id", "summary", "evidence_ids"], "properties": {"id": {"type": "string", "minLength": 1}, "summary": {"type": "string", "minLength": 1}, "evidence_ids": {"$ref": "#/$defs/recordIds"}, "owner": {"type": ["string", "null"]}, "rationale": {"type": ["string", "null"]}}},
62	    "records": {"type": "array", "items": {"$ref": "#/$defs/record"}},
63	    "sourceRecord": {"allOf": [{"$ref": "#/$defs/record"}, {"type": "object", "required": ["source_role", "authority", "locator", "retrieved_at", "retrieval_status", "content_type", "version_metadata", "content_hash", "local_reference"], "properties": {"source_role": {"enum": ["binding-regulation", "official-guidance", "internal-policy", "operational-record", "other"]}, "authority": {"enum": ["binding", "advisory", "internal-control", "operational-evidence", "unknown"]}, "locator": {"type": "string", "minLength": 1}, "retrieved_at": {"type": "string", "format": "date-time"}, "retrieval_status": {"enum": ["retrieved", "unavailable", "invalid", "unverified", "stale"]}, "content_type": {"type": "string", "minLength": 1}, "version_metadata": {"type": ["object", "null"]}, "content_hash": {"anyOf": [{"type": "string", "pattern": "^sha256:[0-9a-f]{64}$"}, {"type": "null"}]}, "local_reference": {"type": ["string", "null"]}}}]},
64	    "impactRecord": {"allOf": [{"$ref": "#/$defs/record"}, {"type": "object", "required": ["state"], "properties": {"state": {"enum": ["supported-impact", "supported-no-impact", "conflicting", "unresolved"]}}}]},
65	    "approvalRecord": {"allOf": [{"$ref": "#/$defs/record"}, {"type": "object", "required": ["status"], "properties": {"status": {"enum": ["pending", "approved", "rejected", "not-required"]}}}]},
66	    "decisionRecord": {"allOf": [{"$ref": "#/$defs/record"}, {"type": "object", "required": ["rationale", "tradeoffs"], "properties": {"rationale": {"type": "string", "minLength": 1}, "tradeoffs": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}}}}]},
67	    "artifactRecord": {"type": "object", "additionalProperties": true, "required": ["id", "path", "sha256", "validation_status"], "properties": {"id": {"type": "string", "minLength": 1}, "path": {"type": "string", "minLength": 1}, "sha256": {"type": "string", "pattern": "^sha256:[0-9a-f]{64}$"}, "validation_status": {"enum": ["valid", "invalid", "not-produced"]}}}
68	  }
69	}
